class Solution {
public:
    bool checkTwoChessboards(string coordinate1, string coordinate2) {
        int c1 = (coordinate1[0] - 'a' + coordinate1[1] - '0') % 2;
        int c2 = (coordinate2[0] - 'a' + coordinate2[1] - '0') % 2;
        return c1 == c2;
    }
};

class Solution {
    public boolean checkTwoChessboards(String coordinate1, String coordinate2) {
        int c1 = (coordinate1.charAt(0) - 'a' + coordinate1.charAt(1) - '0') % 2;
        int c2 = (coordinate2.charAt(0) - 'a' + coordinate2.charAt(1) - '0') % 2;
        return c1 == c2;
    }
}

var checkTwoChessboards = function(coordinate1, coordinate2) {
    const c1 = (coordinate1.charCodeAt(0) - 97 + parseInt(coordinate1[1], 10)) % 2;
    const c2 = (coordinate2.charCodeAt(0) - 97 + parseInt(coordinate2[1], 10)) % 2;
    return c1 === c2;
};
